#include <cassert>
#include <stdexcept>
#include <vector>
#include "all_your_base.h"

int main() {
    using all_your_base::convert;

    assert((convert(2, std::vector<unsigned int>{1, 0}, 10) == std::vector<unsigned int>{2}));
    assert((convert(10, std::vector<unsigned int>{0}, 2)).empty());
    assert((convert(3, std::vector<unsigned int>{0, 1, 2, 0}, 16) == std::vector<unsigned int>{0, 5}));
    assert((convert(16, std::vector<unsigned int>{0, 5}, 3) == std::vector<unsigned int>{1, 2, 0}));

    bool threw = false;
    try { convert(2, std::vector<unsigned int>{1, 2}, 10); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);

    threw = false;
    try { convert(1, std::vector<unsigned int>{}, 10); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);

    threw = false;
    try { convert(10, std::vector<unsigned int>{1}, 0); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);

    return 0;
}
